// Specialized kernel for GEMM where N and K are small relative to M.
// This matches a tall-and-skinny problem shape (M >> N, K): we tile only
// over the large M dimension (one CTA covers a chunk of rows, one thread
// per row) and keep the small N,K dimensions entirely inside the CTA:
// B (the small K x N operand) is staged once into shared memory per CTA
// and reused by every thread/row in that CTA, while the K-reduction and
// N-outputs are kept in registers and unrolled.
template <int MAX_N>
__global__ void gemm_tallskinny_kernel(const float* __restrict__ A,
                                        const float* __restrict__ B,
                                        float* __restrict__ C,
                                        int M, int N, int K) {
  extern __shared__ float sB[]; // K*N floats, row-major (k*N + n)
  int tid = threadIdx.x;
  int nthreads = blockDim.x;
  int KN = K * N;
  for (int idx = tid; idx < KN; idx += nthreads) {
    sB[idx] = B[idx];
  }
  __syncthreads();
  int row = blockIdx.x * blockDim.x + tid;
  if (row < M) {
    float acc[MAX_N];
    #pragma unroll
    for (int n = 0; n < MAX_N; ++n) {
      if (n < N) acc[n] = 0.0f;
    }
    const float* Arow = A + (size_t)row * K;
    for (int k = 0; k < K; ++k) {
      float a = Arow[k];
      const float* sBk = sB + k * N;
      #pragma unroll
      for (int n = 0; n < MAX_N; ++n) {
        if (n < N) acc[n] += a * sBk[n];
      }
    }
    float* Crow = C + (size_t)row * N;
    #pragma unroll
    for (int n = 0; n < MAX_N; ++n) {
      if (n < N) Crow[n] = acc[n];
    }
  }
}
template <int MAX_N>
static void launch_tallskinny(const float* ptrA, const float* ptrB, float* ptrC,
                               int M, int N, int K, cudaStream_t stream) {
